  function restoreEl(el){for(const a of ATTR){const key="data-i18n-"+a;if(el.hasAttribute(key)){if(el.getAttribute(a)===el.getAttribute(key+"-en"))el.setAttribute(a,el.getAttribute(key));el.removeAttribute(key);el.removeAttribute(key+"-en");}}}
  let busy=false;
